he two admitted EIA series only; private authorised use, attribution and upstream terms remain binding","ownerApprovalNeeded":"Permit renewable administrative leases under existing accepted business rights; no automatic extension of a real finite provider agreement"},"sqlSha256":{"apps/platform-source-hub/migrations/010-ecr-source-continuity.sql":"fa2a62451e890a1f239dfc67278f7ad943a4c3e172e4de53397cfe58e71e91a0","packages/platform-contracts/current-e1-authority/migrations/011-ecr-source-continuity.sql":"3f18fa53b7ebcd6c6674a6014dabcda5b87f395cdddeeca1f0edd2df926007d1"},"newInfrastructure":false,"newPaidEndpoints":false,"newSourceFamilies":false,"newE1ServiceIdentity":false,"rollback":"Disable monitor and roll back existing cron to retained exact LKG artifact; set source continuity owner policy REVOKED to stop renewal. Preserve audit, data, keys and finite leases; no global database restore."}$plan$::jsonb; supplied jsonb; basis text;
BEGIN
 supplied:=nullif(current_setting('ecr.source_access_plan',true),'')::jsonb;
 basis:=current_setting('ecr.source_access_owner_ref',true);
 IF current_user<>'source_hub_development_owner' OR supplied IS DISTINCT FROM expected OR basis IS NULL OR basis!~'^owner-decision:sha256:[a-f0-9]{64}$'
 OR NOT EXISTS(SELECT 1 FROM source_hub.installation WHERE singleton AND environment='development'
 AND project_id=expected->'sourceHub'->>'projectId' AND branch_id=expected->'sourceHub'->>'branchId' AND database_name=current_database())
 OR current_database()<>expected->'sourceHub'->>'databaseName' THEN RAISE EXCEPTION 'EXACT_ECR_SOURCE_ACCESS_OWNER_PLAN_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM source_hub.ecr_source_continuity_policy) THEN RAISE EXCEPTION 'SOURCE_CONTINUITY_EXISTS_RECONCILE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=expected->'sourceHub'->>'newMonitorRole' AND rolcanlogin
 AND NOT(rolsuper OR rolinherit OR rolbypassrls OR rolcreaterole OR rolcreatedb OR rolreplication)
 AND NOT EXISTS(SELECT 1 FROM pg_auth_members WHERE member=oid)) THEN RAISE EXCEPTION 'EXACT_ORDINARY_MONITOR_ROLE_REQUIRED'; END IF;
 INSERT INTO source_hub.ecr_source_continuity_policy(singleton,status,owner_basis,rights_mode,rights_valid_until,expected_fingerprints,lease_until)
 VALUES(true,'ACTIVE',basis,expected->'sourceHub'->>'rightsMode',(expected->'sourceHub'->>'rightsValidUntil')::timestamptz,expected->'sourceHub'->'expectedFingerprints',(expected->'sourceHub'->>'initialLeaseUntil')::timestamptz);
END $activate$;
